{
  "name": "OpenFlexure 电动位移台",
  "name_en": "OpenFlexure motorized translation stage",
  "manufacturer": "",
  "description": "一种通过串口控制的电动位移台，通常由步进电机驱动，用于多轴样品或光学部件定位。它可执行相对/绝对移动、Z 轴对焦扫描、线性扫描以及基于限位的回零，常用于显微成像、样品定位和重复扫描实验。",
  "description_en": "A serial-controlled motorized translation stage, typically driven by stepper motors, for multi-axis positioning of samples or optical components. It supports relative/absolute motion, Z-axis focus scans, linear scans, and endstop-based homing, and is commonly used in microscopy, sample positioning, and repeatable scanning experiments.",
  "tag_hints": [
    "motorized translation stage",
    "XYZ positioning",
    "microscopy positioning",
    "focus scanning",
    "stepper motor stage",
    "endstop homing",
    "light sensor"
  ],
  "actions": [
    {
      "action_name": "auto-backlash",
      "description": "获取/设置回程间隙补偿距离",
      "description_en": "get/set the backlash compensation distance"
    },
    {
      "action_name": "auto-move_rel",
      "description": "按相对位移移动位移台",
      "description_en": "move the stage by a relative displacement"
    },
    {
      "action_name": "auto-release_motors",
      "description": "释放电机并使步进电机线圈断电",
      "description_en": "release the motors and de-energize the stepper coils"
    },
    {
      "action_name": "auto-move_abs",
      "description": "将位移台移动到绝对位置",
      "description_en": "move the stage to an absolute position"
    },
    {
      "action_name": "auto-focus_rel",
      "description": "沿 Z 轴作相对移动以调焦",
      "description_en": "move relatively along the Z axis for focusing"
    },
    {
      "action_name": "auto-scan_linear",
      "description": "按给定相对位置序列执行线性扫描",
      "description_en": "perform a linear scan through a sequence of relative positions"
    },
    {
      "action_name": "auto-scan_z",
      "description": "按给定 Z 轴相对位置序列执行扫描",
      "description_en": "perform a scan through a sequence of relative Z positions"
    },
    {
      "action_name": "auto-query",
      "description": "向位移台控制器发送直接命令并读取响应",
      "description_en": "send a direct command to the stage controller and read the response"
    },
    {
      "action_name": "auto-list_modules",
      "description": "列出控制器已安装的可选模块",
      "description_en": "list the optional modules installed on the controller"
    },
    {
      "action_name": "auto-print_help",
      "description": "显示控制器内置帮助信息",
      "description_en": "display the controller's built-in help information"
    },
    {
      "action_name": "auto-test_mode",
      "description": "获取/设置测试模式",
      "description_en": "get/set the test mode"
    },
    {
      "action_name": "auto-n_axes",
      "description": "获取位移台轴数",
      "description_en": "get the number of stage axes"
    },
    {
      "action_name": "auto-gain",
      "description": "获取/设置光传感器增益",
      "description_en": "get/set the light sensor gain"
    },
    {
      "action_name": "auto-home",
      "description": "使用限位开关执行回零",
      "description_en": "home the stage using the endstops"
    }
  ]
}

